public class ExchangeRateClient {
    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String normalisedBase = normaliseCurrency(baseCurrency);
        Set<String> normalisedQuotes = new Set<String>();
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies must be provided.');
        }
        for (String q : quoteCurrencies) {
            normalisedQuotes.add(normaliseCurrency(q));
        }

        String symbolsParam = String.join(new List<String>(normalisedQuotes), ',');

        HttpRequest request = new HttpRequest();
        request.setEndpoint(ENDPOINT + '?base=' + normalisedBase + '&symbols=' + symbolsParam);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');

        HttpResponse response = new Http().send(request);

        if (response.getStatusCode() == 503) {
            response = new Http().send(request);
        }

        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException('Callout failed with status code: ' + response.getStatusCode());
        }

        Map<String, Object> parsed = (Map<String, Object>) JSON.deserializeUntyped(response.getBody());
        Map<String, Object> rates = (Map<String, Object>) parsed.get('rates');
        if (rates == null) {
            throw new ExchangeRateException('Unable to parse rates from response body.');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String quote : normalisedQuotes) {
            Object rateObj = rates.get(quote);
            if (rateObj == null) {
                throw new ExchangeRateException('No rate returned for currency: ' + quote);
            }
            Decimal rate = (Decimal) rateObj;
            result.put(quote, rate);
        }

        return result;
    }

    private static String normaliseCurrency(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code cannot be null.');
        }
        String normalised = code.trim().toUpperCase();
        if (normalised.length() != 3 || !normalised.matches('[A-Z]{3}')) {
            throw new ExchangeRateException('Invalid currency code: ' + code);
        }
        return normalised;
    }
}
