public class PaymentTerms {

    public static Integer parseNetDays(String terms) {
        String originalInput = terms;

        if (terms == null) {
            throw new UnsupportedTermsException('Unsupported payment terms: null');
        }

        String trimmedTerms = terms.trim();

        if (trimmedTerms == '') {
            throw new UnsupportedTermsException('Unsupported payment terms: ' + originalInput);
        }

        String normalizedTerms = trimmedTerms.toUpperCase();

        if (normalizedTerms == 'DUE ON RECEIPT') {
            return 0;
        }

        Pattern netPattern = Pattern.compile('^NET\\s*(\\d{1,3})$');
        Matcher netMatcher = netPattern.matcher(normalizedTerms);

        if (netMatcher.matches()) {
            Integer days = Integer.valueOf(netMatcher.group(1));
            if (days > 180) {
                throw new TermsOutOfRangeException('Net days out of range: ' + days);
            }
            return days;
        }

        throw new UnsupportedTermsException('Unsupported payment terms: ' + originalInput);
    }

    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        return invoiceDate + netDays;
    }
}
