public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ---- Validate maxRows ----
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // ---- Validate object name ----
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name cannot be blank.');
        }

        String normalizedObject;
        try {
            Schema.SObjectType sObjectType = Schema.getGlobalDescribe().get(objectApiName);
            if (sObjectType == null) {
                throw new SearchException('Object "' + objectApiName + '" does not exist.');
            }
            Schema.DescribeSObjectResult dsor = sObjectType.getDescribe();
            normalizedObject = dsor.getName();
        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException('Object "' + objectApiName + '" does not exist.');
        }

        Schema.DescribeSObjectResult objectDescribe = Schema.getGlobalDescribe().get(normalizedObject).getDescribe();
        if (!objectDescribe.isAccessible()) {
            throw new SearchException('Running user cannot access object "' + normalizedObject + '".');
        }

        // ---- Validate fields list ----
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('Fields list cannot be null or empty.');
        }

        List<String> validatedFields = new List<String>();
        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Field name in fields list cannot be blank.');
            }
            String normalizedField = normalizeFieldName(objectDescribe, f);
            if (normalizedField == null) {
                throw new SearchException('Field "' + f + '" does not exist on object "' + normalizedObject + '".');
            }
            if (!isFieldReadable(objectDescribe, normalizedField)) {
                throw new SearchException('Running user cannot read field "' + normalizedField + '" on object "' + normalizedObject + '".');
            }
            validatedFields.add(normalizedField);
        }

        // ---- Validate filters ----
        Map<String, Object> validatedFilters = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            for (String filterField : filters.keySet()) {
                if (String.isBlank(filterField)) {
                    throw new SearchException('Filter field name cannot be blank.');
                }
                String normalizedFilterField = normalizeFieldName(objectDescribe, filterField);
                if (normalizedFilterField == null) {
                    throw new SearchException('Filter field "' + filterField + '" does not exist on object "' + normalizedObject + '".');
                }
                if (!isFieldAccessible(objectDescribe, normalizedFilterField)) {
                    throw new SearchException('Filter field "' + normalizedFilterField + '" cannot be filtered.');
                }
                validatedFilters.put(normalizedFilterField, filters.get(filterField));
            }
        }

        // ---- Validate orderByField ----
        if (String.isNotBlank(orderByField)) {
            String normalizedOrderBy = normalizeFieldName(objectDescribe, orderByField);
            if (normalizedOrderBy == null) {
                throw new SearchException('Order-by field "' + orderByField + '" does not exist on object "' + normalizedObject + '".');
            }
            if (!isFieldSortable(objectDescribe, normalizedOrderBy)) {
                throw new SearchException('Order-by field "' + normalizedOrderBy + '" cannot be sorted.');
            }
            orderByField = normalizedOrderBy;
        }

        // ---- Build query ----
        List<String> fieldListForQuery = new List<String>{ 'Id' };
        fieldListForQuery.addAll(validatedFields);

        String query = 'SELECT ' + String.join(fieldListForQuery, ', ') + ' FROM ' + normalizedObject;

        if (validatedFilters != null && !validatedFilters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String f : validatedFilters.keySet()) {
                Object val = validatedFilters.get(f);
                conditions.add(wrapCondition(f, val));
            }
            query += ' WHERE ' + String.join(conditions, ' AND ');
        }

        if (String.isNotBlank(orderByField)) {
            query += ' ORDER BY ' + orderByField + ' ASC';
        }

        query += ' LIMIT ' + maxRows;

        try {
            return Database.query(query);
        } catch (Exception e) {
            throw new SearchException('Query failed: ' + e.getMessage());
        }
    }

    // ---- Helpers ----

    private static String normalizeFieldName(Schema.DescribeSObjectResult dsor, String fieldName) {
        Map<String, Schema.SObjectField> fieldMap = dsor.fields.getMap();
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldName)) {
                Schema.SObjectField sof = fieldMap.get(key);
                return sof.getDescribe().getName();
            }
        }
        return null;
    }

    private static Boolean isFieldReadable(Schema.DescribeSObjectResult dsor, String fieldName) {
        Map<String, Schema.SObjectField> fieldMap = dsor.fields.getMap();
        Schema.SObjectField sof = fieldMap.get(fieldName);
        if (sof == null) {
            return false;
        }
        return sof.getDescribe().isAccessible();
    }

    private static Boolean isFieldAccessible(Schema.DescribeSObjectResult dsor, String fieldName) {
        Map<String, Schema.SObjectField> fieldMap = dsor.fields.getMap();
        Schema.SObjectField sof = fieldMap.get(fieldName);
        if (sof == null) {
            return false;
        }
        return sof.getDescribe().isAccessible();
    }

    private static Boolean isFieldSortable(Schema.DescribeSObjectResult dsor, String fieldName) {
        Map<String, Schema.SObjectField> fieldMap = dsor.fields.getMap();
        Schema.SObjectField sof = fieldMap.get(fieldName);
        if (sof == null) {
            return false;
        }
        return sof.getDescribe().isSortable();
    }

    private static String wrapCondition(String field, Object value) {
        if (value == null) {
            return field + ' = null';
        } else if (value instanceof String) {
            String escaped = escapeForSoql(String.valueOf(value));
            return field + ' = \'' + escaped + '\'';
        } else if (value instanceof Boolean) {
            return field + ' = ' + (Boolean)value;
        } else if (value instanceof Date) {
            Date d = (Date)value;
            String dateStr = String.format('{0}-{1}-{2}', new List<String>{
                String.valueOf(d.year()),
                String.valueOf(d.month()).leftPad(2, '0'),
                String.valueOf(d.day()).leftPad(2, '0')
            });
            return field + ' = ' + dateStr;
        } else if (value instanceof DateTime) {
            DateTime dt = (DateTime)value;
            String datetimeStr = String.format('{0}-{1}-{2}T{3}:{4}:{5}', new List<String>{
                String.valueOf(dt.year()),
                String.valueOf(dt.month()).leftPad(2, '0'),
                String.valueOf(dt.day()).leftPad(2, '0'),
                String.valueOf(dt.hour()).leftPad(2, '0'),
                String.valueOf(dt.minute()).leftPad(2, '0'),
                String.valueOf(dt.second()).leftPad(2, '0')
            });
            return field + ' = ' + datetimeStr;
        } else if (value instanceof Decimal) {
            return field + ' = ' + String.valueOf(value);
        } else if (value instanceof Integer) {
            return field + ' = ' + String.valueOf(value);
        } else if (value instanceof Id) {
            String escaped = escapeForSoql(String.valueOf(value));
            return field + ' = \'' + escaped + '\'';
        } else {
            throw new SearchException('Unsupported filter value type for field "' + field + '".');
        }
    }

    private static String escapeForSoql(String input) {
        if (input == null) return '';
        // Escape backslashes first, then single quotes
        String escaped = input.replace('\\', '\\\\');
        return String.escapeSingleQuotes(escaped);
    }
