public with sharing class ContactLookupAction {
    public class Request {
        @InvocableVariable(required=true, description='The email address to look up the contact by')
        public String email;
    }

    public class Result {
        @InvocableVariable(required=false, description='The Id of the contact found, if any')
        public Id contactId;

        @InvocableVariable(required=false, description='Whether a contact was found for the provided email')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing contact by matching the provided email address case-insensitively')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        // Initialize results list with one Result per request, in order
        for (Integer i = 0; i < requests.size(); i++) {
            results.add(new Result(contactId = null, found = false));
        }

        // Collect non-blank emails for querying
        List<String> emailsToQuery = new List<String>();
        for (Request req : requests) {
            if (req != null && req.email != null && String.isNotBlank(req.email.trim())) {
                emailsToQuery.add(req.email.trim());
            }
        }

        if (!emailsToQuery.isEmpty()) {
            // Run a single SOQL query to find contacts matching the emails
            // Order by CreatedDate ASC to ensure earliest created contact is selected when duplicates exist
            List<Contact> matchingContacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emailsToQuery
                ORDER BY CreatedDate ASC
            ];

            // Build a map of email -> contactId, keeping only the first occurrence (earliest CreatedDate)
            Map<String, Id> emailToContactId = new Map<String, Id>();
            for (Contact c : matchingContacts) {
                String normalizedEmail = c.Email.trim();
                if (!emailToContactId.containsKey(normalizedEmail)) {
                    emailToContactId.put(normalizedEmail, c.Id);
                }
            }

            // Now populate the results based on the original requests
            for (Integer i = 0; i < requests.size(); i++) {
                Request req = requests[i];
                if (req != null && req.email != null && String.isNotBlank(req.email.trim())) {
                    String normalizedInput = req.email.trim();
                    Id matchedId = emailToContactId.get(normalizedInput);
                    if (matchedId != null) {
                        results[i].contactId = matchedId;
                        results[i].found = true;
                    }
                }
            }
        }

        return results;
    }
}
