public class OrderPayloadParser {
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    private static Boolean isBlank(String s) {
        return s == null || s.trim().length() == 0;
    }

    public static Order parse(String body) {
        if (body == null || isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON');
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('JSON is not an object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        String orderNum = (String) root.get('number');
        if (orderNum == null || isBlank(orderNum)) {
            throw new PayloadException('Missing or blank order number');
        }

        Order order = new Order();
        order.orderNumber = orderNum;
        order.currencyCode = (String) root.get('currency');
        order.lines = new List<Line>();
        order.total = Decimal.valueOf(0);

        // Parse date
        String dateStr = (String) root.get('date');
        if (dateStr != null && !isBlank(dateStr)) {
            order.orderDate = Date.valueOf(dateStr);
        }

        // Parse customer
        Object customerObj = root.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Map<String, Object> customerMap = (Map<String, Object>) customerObj;
            order.customerEmail = (String) customerMap.get('email');
        }

        // Parse lines
        Object linesObj = root.get('lines');
        List<Line> lines = new List<Line>();
        if (linesObj instanceof List<Object>) {
            for (Object lineObj : (List<Object>) linesObj) {
                lines.add(parseLine(lineObj));
            }
        }
        order.lines = lines;

        // Calculate total
        Decimal total = 0;
        for (Line line : lines) {
            total = total + line.lineTotal;
        }
        order.total = total;

        return order;
    }

    private static Line parseLine(Object lineObj) {
        if (!(lineObj instanceof Map<String, Object>)) {
            throw new PayloadException('Invalid line: not an object');
        }

        Map<String, Object> lineMap = (Map<String, Object>) lineObj;
        Line line = new Line();

        line.sku = (String) lineMap.get('sku');
        if (line.sku == null || isBlank(line.sku)) {
            throw new PayloadException('Missing sku in line');
        }

        Object quantityObj = lineMap.get('quantity');
        if (quantityObj == null) {
            throw new PayloadException('Missing quantity in line');
        }
        line.quantity = (Integer) quantityObj;
        if (line.quantity == null || line.quantity <= 0) {
            throw new PayloadException('Invalid quantity in line');
        }

        Object unitPriceObj = lineMap.get('unitPrice');
        if (unitPriceObj == null) {
            throw new PayloadException('Missing unitPrice in line');
        }
        Decimal up = (Decimal) unitPriceObj;
        if (up == null || up < 0) {
            throw new PayloadException('Invalid unitPrice in line');
        }
        line.unitPrice = up;

        Object discountObj = lineMap.get('discount');
        if (discountObj == null) {
            line.discount = 0;
        } else {
            line.discount = (Decimal) discountObj;
            if (line.discount < 0 || line.discount > 1) {
                throw new PayloadException('Invalid discount in line');
            }
        }

        line.lineTotal = calculateLineTotal(line.quantity, line.unitPrice, line.discount);

        return line;
    }

    private static Decimal calculateLineTotal(Integer quantity, Decimal unitPrice, Decimal discount) {
        Decimal multiplier = 1 - discount;
        Decimal lineTotal = Decimal.valueOf(quantity) * unitPrice * multiplier;
        return lineTotal.setScale(2, RoundingMode.HALF_UP);
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines.size());
        ack.put('total', order.total);

        return JSON.serialize(ack);
    }
}
