    private static Map<String, Schema.SObjectType> sObjectTypeCache;

    private static Map<String, Schema.SObjectType> getGlobalDescribeCached() {
        if (sObjectTypeCache == null) {
            sObjectTypeCache = Schema.getGlobalDescribe();
        }
        return sObjectTypeCache;
    }

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names cannot be null or blank.');
        }

        try {
            Map<String, Schema.SObjectType> globalDescribe = getGlobalDescribeCached();

            String lowerObjectName = objectApiName.toLowerCase();
            Schema.SObjectType targetSObjectType = null;

            for (String key : globalDescribe.keySet()) {
                if (key.toLowerCase() == lowerObjectName) {
                    targetSObjectType = globalDescribe.get(key);
                    break;
                }
            }

            if (targetSObjectType == null) {
                throw new PicklistServiceException('Object "' + objectApiName + '" does not exist.');
            }

            Schema.DescribeSObjectResult describeResult = targetSObjectType.getDescribe();
            Map<String, Schema.SObjectField> fieldMap = describeResult.fields.getMap();

            String lowerFieldName = fieldApiName.toLowerCase();
            Schema.SObjectField targetField = null;

            for (String fieldKey : fieldMap.keySet()) {
                if (fieldKey.toLowerCase() == lowerFieldName) {
                    targetField = fieldMap.get(fieldKey);
                    break;
                }
            }

            if (targetField == null) {
                throw new PicklistServiceException(
                    'Field "' + fieldApiName + '" does not exist on object "' + objectApiName + '".'
                );
            }

            Schema.DescribeFieldResult fieldDescribe = targetField.getDescribe();
            String fieldTypeStr = String.valueOf(fieldDescribe.getType()).toLowerCase();

            if (!fieldTypeStr.contains('picklist')) {
                throw new PicklistServiceException(
                    'Field "' + fieldApiName + '" on object "' + objectApiName
                    + '" is not a picklist or multi-select picklist.'
                );
            }

            List<Schema.PicklistEntry> picklistEntries = fieldDescribe.getPicklistValues();

            List<Option> options = new List<Option>();

            if (picklistEntries != null) {
                for (Schema.PicklistEntry entry : picklistEntries) {
                    if (entry.isActive()) {
                        options.add(new Option(
                            entry.getValue(),
                            entry.getLabel(),
                            entry.isDefaultValue()
                        ));
                    }
                }
            }

            return options;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Error retrieving picklist values for "' + objectApiName + '.' + fieldApiName
                + '": ' + e.getMessage()
            );
        }
    }
