public class AccountScoringJob implements Queueable {
    private final List<Id> accountIds;
    private static Integer chainDepth = 0;
    private static final Integer MAX_CHAIN_DEPTH = 50;
    private static final Integer SOQL_LIMIT = 100;
    private static final Integer BATCH_SIZE = 200;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds != null) ? new List<Id>(accountIds) : new List<Id>();
    }

    public void execute(QueueableContext ctx) {
        chainDepth++;
        try {
            if (accountIds.isEmpty()) {
                return;
            }

            // Process at most 200 accounts: the first 200 Ids of its list
            Integer batchSize = Math.min(accountIds.size(), BATCH_SIZE);

            List<Id> batchIds = new List<Id>();
            for (Integer i = 0; i < batchSize; i++) {
                batchIds.add(accountIds[i]);
            }

            // One SOQL query per execution
            List<Account> accounts = [
                SELECT Id, AnnualRevenue
                FROM Account
                WHERE Id IN :batchIds
            ];

            // Set Rating from AnnualRevenue
            for (Account acc : accounts) {
                acc.Rating = computeRating(acc.AnnualRevenue);
            }

            // One DML statement per execution
            if (!accounts.isEmpty()) {
                update accounts;
            }

            // If Ids remain, enqueue a new job with the remaining Ids
            if (accountIds.size() > batchSize) {
                List<Id> remainingIds = new List<Id>();
                for (Integer i = batchSize; i < accountIds.size(); i++) {
                    remainingIds.add(accountIds[i]);
                }

                if (chainDepth < MAX_CHAIN_DEPTH) {
                    // Normal chaining - always use enqueueJob (not skipped in tests)
                    System.enqueueJob(new AccountScoringJob(remainingIds));
                } else {
                    // At max depth - split remaining into chunks that fit
                    // within SOQL limits and enqueue them separately
                    splitRemainingIntoChunks(remainingIds);
                }
            }
        } finally {
            chainDepth--;
        }
    }

    private static void splitRemainingIntoChunks(List<Id> remainingIds) {
        Integer totalBatches = Integer.valueOf(Math.ceil((Decimal)remainingIds.size() / BATCH_SIZE));

        if (totalBatches <= (SOQL_LIMIT - 1)) {
            // Can process all remaining iteratively within SOQL limits
            processRemainingIteratively(remainingIds);
        } else {
            // Split into chunks that fit within SOQL limits and enqueue each
            Integer chunkSize = (SOQL_LIMIT - 1) * BATCH_SIZE;
            for (Integer i = 0; i < remainingIds.size(); i += chunkSize) {
                Integer endIndex = Math.min(i + chunkSize, remainingIds.size());
                List<Id> chunk = new List<Id>();
                for (Integer j = i; j < endIndex; j++) {
                    chunk.add(remainingIds[j]);
                }
                System.enqueueJob(new AccountScoringJob(chunk));
            }
        }
    }

    private static void processRemainingIteratively(List<Id> allIds) {
        while (!allIds.isEmpty()) {
            Integer batchSize = Math.min(allIds.size(), BATCH_SIZE);

            List<Id> batchIds = new List<Id>();
            for (Integer i = 0; i < batchSize; i++) {
                batchIds.add(allIds[i]);
            }

            List<Account> accounts = [
                SELECT Id, AnnualRevenue
                FROM Account
                WHERE Id IN :batchIds
            ];

            for (Account acc : accounts) {
                acc.Rating = computeRating(acc.AnnualRevenue);
            }

            if (!accounts.isEmpty()) {
                update accounts;
            }

            // Remove processed records from the list
            List<Id> remaining = new List<Id>();
            for (Integer i = batchSize; i < allIds.size(); i++) {
                remaining.add(allIds[i]);
            }
            allIds = remaining;
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    private static String computeRating(Decimal annualRevenue) {
        if (annualRevenue != null) {
            if (annualRevenue >= 1000000) {
                return 'Hot';
            }
            if (annualRevenue >= 100000) {
                return 'Warm';
            }
        }
        return 'Cold';
    }
