public without sharing class OpportunityPipelineHandler {

    public static void handle(
        List<Opportunity> newRecords,
        List<Opportunity> oldRecords,
        Map<Id, Opportunity> newMap,
        Map<Id, Opportunity> oldMap,
        System.TriggerOperation operation
    ) {
        if (operation == System.TriggerOperation.AFTER_INSERT) {
            handleAfterInsert(newRecords);
        } else if (operation == System.TriggerOperation.AFTER_UPDATE) {
            handleAfterUpdate(newRecords, oldMap);
        } else if (operation == System.TriggerOperation.AFTER_DELETE) {
            handleAfterDelete(oldRecords);
        } else if (operation == System.TriggerOperation.AFTER_UNDELETE) {
            handleAfterUndelete(newRecords);
        }
    }

    private static void handleAfterInsert(List<Opportunity> newRecords) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newRecords) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        if (!accountIds.isEmpty()) {
            recalculateAccounts(accountIds);
        }
    }

    private static void handleAfterUpdate(List<Opportunity> newRecords, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newRecords) {
            Opportunity oldOpp = oldMap.get(opp.Id);
            // Track current account
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
            // Track previous account if changed
            if (oldOpp.AccountId != null && oldOpp.AccountId != opp.AccountId) {
                accountIds.add(oldOpp.AccountId);
            }
        }
        if (!accountIds.isEmpty()) {
            recalculateAccounts(accountIds);
        }
    }

    private static void handleAfterDelete(List<Opportunity> oldRecords) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : oldRecords) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        if (!accountIds.isEmpty()) {
            recalculateAccounts(accountIds);
        }
    }

    private static void handleAfterUndelete(List<Opportunity> newRecords) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newRecords) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        if (!accountIds.isEmpty()) {
            recalculateAccounts(accountIds);
        }
    }

    private static void recalculateAccounts(Set<Id> accountIds) {
        // Query all accounts that need recalculation
        List<Account> accountsToUpdate = new List<Account>();
        List<AggregateResult> pipelineResults = [
            SELECT AccountId,
                   SUM(Amount) openPipeline,
                   COUNT(Id) openOpps
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ];

        // Create map of aggregate results
        Map<Id, AggregateResult> resultByAccount = new Map<Id, AggregateResult>();
        for (AggregateResult ar : pipelineResults) {
            resultByAccount.put((Id)ar.get('AccountId'), ar);
        }

        // Query accounts to update
        for (Id accountId : accountIds) {
            Account acc = new Account(Id = accountId);
            AggregateResult result = resultByAccount.get(accountId);
            if (result != null) {
                Decimal openPipeline = (Decimal)result.get('openPipeline');
                acc.FB_Open_Pipeline__c = (openPipeline != null) ? openPipeline : 0;
                acc.FB_Open_Opportunities__c = Integer.valueOf(result.get('openOpps'));
            } else {
                // No open opportunities for this account
                acc.FB_Open_Pipeline__c = 0;
                acc.FB_Open_Opportunities__c = 0;
            }
            accountsToUpdate.add(acc);
        }

        if (!accountsToUpdate.isEmpty()) {
            try {
                Database.SaveResult[] results = Database.update(accountsToUpdate, false);
            } catch (Exception e) {
                // Log error but don't fail the transaction
                System.debug('Error updating accounts in OpportunityPipelineHandler: ' + e.getMessage());
            }
        }
    }
}
