public with sharing class Opportunities extends fflib_SObjectDomain {

    public Opportunities() {
        super();
    }

    public Opportunities(List<Opportunity> records) {
        super((List<SObject>) records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities((List<Opportunity>) records);
        }
    }

    public override void apply() {
        super.apply();
        applyValidation();
    }

    public void applyValidation() {
        List<Opportunity> recordsToValidate = (List<Opportunity>) getRecords();

        for (Opportunity opp : recordsToValidate) {
            // Rule 1: Amount must not be negative (insert and update)
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }

        // Rule 2: On update, a previously Closed Won opportunity cannot have its Amount changed.
        // Closing an opportunity as won and changing its amount in the same update is allowed.
        if (Trigger.isUpdate) {
            for (Opportunity opp : recordsToValidate) {
                Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
                if (oldOpp != null && 
                    oldOpp.StageName == 'Closed Won' &&
                    opp.Amount != oldOpp.Amount) {
                    error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                }
            }
        }
    }
}
