public with sharing class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        // Handle null or empty input
        if (contactIds == null || contactIds.isEmpty()) {
            return new Map<Id, String>();
        }

        // Query contacts with their Phone field
        List<Contact> contacts = [
            SELECT Id, Phone
            from Contact
            where Id IN :contactIds AND Phone != null
        ];

        // Normalize phone numbers
        for (Contact c : contacts) {
            c.Phone = normalizePhone(c.Phone);
        }

        // Save all contacts with partial success allowed
        List<Database.SaveResult> results = Database.update(contacts, false);

        // Build map of failed saves
        Map<Id, String> failedSaves = new Map<Id, String>();
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess() && results[i].getErrors().size() > 0) {
                failedSaves.put(contacts[i].Id, results[i].getErrors()[0].getMessage());
            }
        }

        return failedSaves;
    }

    private static String normalizePhone(String phone) {
        if (String.isBlank(phone)) {
            return phone;
        }

        String result = '';
        for (Integer i = 0; i < phone.length(); i++) {
            String charAtIndex = phone.substring(i, i + 1);
            // Keep only digits and '+' characters
            if (charAtIndex.isNumeric() || charAtIndex == '+') {
                result += charAtIndex;
            }
        }
        return result;
    }
}

