public class AccountRatingService {

    /**
     * Asynchronously recalculates the Rating field on the given Accounts
     * based on their open opportunities:
     * - Hot: At least one open opportunity with Amount >= 100,000
     * - Warm: Open opportunities exist but none with Amount >= 100,000
     * - Cold: No open opportunities
     */
    @future
    public static void recalculate(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) return;

        try {
            // Query all open opportunities for these accounts
            List<Opportunity> openOpps = [
                SELECT Id, AccountId, Amount 
                FROM Opportunity 
                WHERE AccountId IN :accountIds 
                  AND IsClosed = false
            ];

            // Group opportunities by account
            Map<Id, List<Opportunity>> oppsByAccount = new Map<Id, List<Opportunity>>();
            for (Id accountId : accountIds) {
                oppsByAccount.put(accountId, new List<Opportunity>());
            }

            for (Opportunity opp : openOpps) {
                if (oppsByAccount.containsKey(opp.AccountId)) {
                    oppsByAccount.get(opp.AccountId).add(opp);
                }
            }

            // Calculate ratings for each account
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accountId : accountIds) {
                List<Opportunity> accountOpps = oppsByAccount.get(accountId);

                String newRating;
                if (accountOpps.isEmpty()) {
                    newRating = 'Cold';
