                    Boolean hasLargeOpp = false;
                    for (Opportunity opp : accountOpps) {
                        if (opp.Amount != null && opp.Amount >= 100000) {
                            hasLargeOpp = true;
                            break;
                        }
                    }
                    newRating = hasLargeOpp ? 'Hot' : 'Warm';
                }

                accountsToUpdate.add(new Account(Id = accountId, Rating = newRating));
            }

            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate;
            }

        } catch (DmlException e) {
            System.debug('Failed to update account ratings: ' + e.getMessage());
