public with sharing class LeadContactMatcher {
    /**
     * For each Lead, finds the first Contact (in the order provided) that has a
     * matching email (case-insensitive and ignoring leading/trailing spaces).
     * A Lead or Contact with a blank email never matches.
     *
     * @param leads   The Leads to match against Contacts.
     * @param contacts The Contacts to search for matching emails.
     * @return A List of Contact Ids with the same size and order as `leads`.
     *         For each Lead, contains the Id of the matching Contact or null.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        // Result list initialized to null for all leads, maintaining order and size
        List<Id> matchedContactIds = new List<Id>();
        for (Integer i = 0; i < leads.size(); i++) {
            matchedContactIds.add(null);
        }

        // If either input is empty, return the result as-is (all nulls)
        if (leads == null || leads.isEmpty() || contacts == null || contacts.isEmpty()) {
            return matchedContactIds;
        }

        // Build a map of normalized email to the first Contact with that email
        // This ensures we get the first contact in list order and avoids nested loop
        Map<String, Id> emailToFirstContactId = new Map<String, Id>();

        for (Contact c : contacts) {
            String email = c.Email;
            // Skip contacts with blank emails
            if (String.isBlank(email)) {
                continue;
            }

            // Normalize: trim and convert to lowercase for case-insensitive matching
            String normalizedEmail = email.trim().toLowerCase();

            // Only add to map if this email hasn't been seen before
            // This preserves the first contact in list order
            if (!emailToFirstContactId.containsKey(normalizedEmail)) {
                emailToFirstContactId.put(normalizedEmail, c.Id);
            }
        }

        // For each lead, check if there's a matching contact
        for (Integer i = 0; i < leads.size(); i++) {
            Lead l = leads[i];
            String leadEmail = l.Email;

            // Skip if the lead's email is blank
            if (String.isBlank(leadEmail)) {
                continue; // matchedContactIds[i] stays null
            }

            // Normalize the lead's email
            String normalizedLeadEmail = leadEmail.trim().toLowerCase();

            // Look up in the map - O(1) operation
            if (emailToFirstContactId.containsKey(normalizedLeadEmail)) {
                matchedContactIds[i] = emailToFirstContactId.get(normalizedLeadEmail);
            }
        }

        return matchedContactIds;
    }
}
