        const listViewPageRef = {
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Case',
                actionName: 'list'
            },
            state: {
                filterName: 'My_Open_Cases'
            }
        };

        this[NavigationMixin.GenerateUrl](listViewPageRef)
            .then((url) => {
                this.casesUrl = url;
            })
            .catch((error) => {
                // eslint-disable-next-line no-console
                console.error('Error generating cases URL', error);
            });
    }

    handleAction(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'new-contact') {
            this.navigateToNewContact();
        } else if (action === 'contacts') {
            this.navigateToContacts();
        } else if (action === 'edit') {
            this.navigateToEdit();
        }
    }

    navigateToNewContact() {
        const defaultValues = encodeDefaultFieldValues({
            AccountId: this.recordId
        });

        const pageReference = {
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Contact',
                actionName: 'new'
            },
            state: {
                defaultFieldValues: defaultValues
            }
        };

        this[NavigationMixin.Navigate](pageReference);
    }

    navigateToContacts() {
        const pageReference = {
            type: 'standard__recordRelationshipPage',
            attributes: {
                objectApiName: 'Account',
                relationshipApiName: 'Contacts',
                actionName: 'view'
            },
            state: {
                recordId: this.recordId
            }
        };

        this[NavigationMixin.Navigate](pageReference);
    }

    navigateToEdit() {
        const pageReference = {
            type: 'standard__recordPage',
            attributes: {
                recordId: this.recordId,
                actionName: 'edit'
            }
        };

        this[NavigationMixin.Navigate](pageReference);
    }
}
