import { LightningElement, api, track } from 'lwc';
import { NavigationMixin } from 'navigation';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { deleteRecord } from 'lightning/uiRecordApi';
import LightningConfirm from 'lightning/confirm';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    _opportunities = [];
    _displayedOpportunities = [];

    @api
    get opportunities() {
        return this._opportunities;
    }
    set opportunities(value) {
        this._opportunities = value || [];
        this.refreshDisplayedOpportunities();
    }

    @track
    get displayedOpportunities() {
        return this._displayedOpportunities;
    }
    set displayedOpportunities(value) {
        this._displayedOpportunities = value;
    }

    columns = [
        { label: 'Name', fieldName: 'Name' },
        { label: 'Stage', fieldName: 'StageName' },
        { label: 'Amount', fieldName: 'Amount', type: 'currency' },
        {
            type: 'action',
            typeAttributes: {
                rowActions: [
                    { label: 'View', name: 'view' },
                    { label: 'Edit', name: 'edit' },
                    { label: 'Delete', name: 'delete' }
                ]
            }
        }
    ];

    refreshDisplayedOpportunities() {
        this._displayedOpportunities = [...this._opportunities];
    }

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        if (actionName === 'view') {
            this.navigateToRecord(row.Id, 'view');
        } else if (actionName === 'edit') {
            this.navigateToRecord(row.Id, 'edit');
        } else if (actionName === 'delete') {
            this.handleDelete(row);
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId: recordId,
                actionName: actionName
            }
        });
    }

    async handleDelete(row) {
        const result = await LightningConfirm.open({
            message: 'Are you sure you want to delete this opportunity?',
            title: 'Confirm Delete',
            variant: 'destructive'
        });

        if (result) {
            try {
                await deleteRecord(row.Id);
                this._displayedOpportunities = this._displayedOpportunities.filter(
                    (opp) => opp.Id !== row.Id
                );
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Opportunity deleted',
                        variant: 'success'
                    })
                );
            } catch (error) {
                let message = '';
                if (error && error.body && error.body.message) {
                    message = error.body.message;
                }
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Delete failed',
                        message: message,
                        variant: 'error'
                    })
                );
            }
        }
    }
}
