public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        // Handle null or empty list
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Initialize results in input order
        for (Integer i = 0; i < gifts.size(); i++) {
            results.add(new ImportResult());
        }

        // Stage one NPSP Data Import record per gift
        List<npsp__DataImport__c> dataImportsToInsert = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c = gift.firstName;
            di.npsp__Contact1_Lastname__c = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;
            di.npsp__Donation_Amount__c = gift.amount;
            di.npsp__Donation_Date__c = gift.giftDate;
            // npsp__Donation_Donor__c defaults to Contact1
            dataImportsToInsert.add(di);
        }

        // Mapping from input position to Data Import record Id
        Map<Integer, Id> positionToImportId = new Map<Integer, Id>();

        // Insert Data Import records one by one to capture errors
        for (Integer i = 0; i < dataImportsToInsert.size(); i++) {
            npsp__DataImport__c singleImport = dataImportsToInsert[i];
            try {
                insert singleImport;
                positionToImportId.put(i, singleImport.Id);
            } catch (DmlException e) {
                results[i].success = false;
                results[i].errorMessage = e.getMessage();
            }
        }

        // Process staged imports synchronously using NPSP's API
        List<Id> stagedImportIds = new List<Id>(positionToImportId.values());
        if (!stagedImportIds.isEmpty()) {
            // Use NPSP's Data Import Service to process synchronously
            npsp.DataImportService.processDataImports(stagedImportIds);
        }

        // Query final state of processed Data Import records
        if (!stagedImportIds.isEmpty()) {
            Map<Id, npsp__DataImport__c> finalRecords = new Map<Id, npsp__DataImport__c>(
                [SELECT Id, npsp__Status__c, npsp__Contact1Imported__c,
                        npsp__DonationImported__c, npsp__FailureInformation__c
                 FROM npsp__DataImport__c
                 WHERE Id IN :stagedImportIds]
            );

            // Build results in original input order
            for (Integer i = 0; i < dataImportsToInsert.size(); i++) {
                Id stagedId = positionToImportId.get(i);
                if (stagedId != null) {
                    npsp__DataImport__c record = finalRecords.get(stagedId);
                    if (record != null && record.npsp__Status__c == 'Imported') {
                        results[i].success = true;
                        results[i].contactId = record.npsp__Contact1Imported__c;
                        results[i].opportunityId = record.npsp__DonationImported__c;
                        results[i].errorMessage = null;
                    } else if (record != null) {
                        results[i].success = false;
                        results[i].contactId = record.npsp__Contact1Imported__c;
                        results[i].opportunityId = record.npsp__DonationImported__c;
                        results[i].errorMessage = record.npsp__FailureInformation__c;
                    }
                }
            }
        }

        return results;
    }
}
