    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate all requests before any DML
        for (GiftRequest req : requests) {
            if (req == null || req.contactId == null || req.amount == null || req.amount <= 0
                || req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31
                || req.startDate == null) {
                throw new RecurringGiftException('Invalid gift request: contact, amount, dayOfMonth, and startDate are required and must be valid.');
            }
        }

        List<npe03__Recurring_Donation__c> rdsToInsert = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();
            rd.npe03__Contact__c = req.contactId;
            rd.npe03__Amount__c = req.amount;
            rd.npe03__Installment_Period__c = 'Month(s)';
            rd.npe03__Schedule_Type__c = 'Monthly';
            rd.npe03__Open_Ended_Status__c = (req.installments == null || req.installments == 0) ? 'Forever' : 'No End Date';
            rd.npe03__Installments__c = (req.installments == null || req.installments == 0) ? null : req.installments;
            rd.npe03__Date_Established__c = req.startDate;
            rd.npe03__Next_Payment_Date__c = req.startDate;
            rd.npsp__RecurringType__c = 'Monthly';
            rd.npsp__InstallmentFrequency__c = 'Month(s)';
            rd.npsp__Day_of_Month__c = (req.dayOfMonth == 31) ? 1 : req.dayOfMonth;
            rd.npsp__Always_Use_Last_Day_Of_Month__c = (req.dayOfMonth == 31);
            rd.npsp__StartDate__c = req.startDate;
            rd.npsp__Status__c = 'Active';
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            rdsToInsert.add(rd);
        }

        insert rdsToInsert;

        List<Id> resultIds = new List<Id>();
        for (Integer i = 0; i < requests.size(); i++) {
            resultIds.add(rdsToInsert[i].Id);
        }

        return resultIds;
    }
