public class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {
        // Validate number of payments
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be at least 1.');
        }

        // Retrieve opportunity with close date and amount
        List<Opportunity> opps = [SELECT Id, Amount, CloseDate, IsClosed FROM Opportunity WHERE Id = :opportunityId LIMIT 1];
        if (opps.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found.');
        }
        Opportunity opp = opps[0];

        // Check if opportunity is closed
        if (opp.IsClosed) {
            throw new PaymentPlanException('Cannot schedule installments for a closed opportunity.');
        }

        // Retrieve all payments for the opportunity
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c, npe01__Written_Off__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opp.Id
        ];

        // Calculate outstanding amount
        Decimal paidAmount = 0;
        Decimal writtenOffAmount = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : existingPayments) {
            if (payment.npe01__Paid__c) {
                paidAmount += payment.npe01__Payment_Amount__c;
            } else if (payment.npe01__Written_Off__c) {
                writtenOffAmount += payment.npe01__Payment_Amount__c;
            } else {
                // Unpaid and not written off - mark for deletion
                paymentsToDelete.add(payment);
            }
        }

        Decimal outstandingAmount = opp.Amount - paidAmount - writtenOffAmount;
        if (outstandingAmount <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero.');
        }

        // Delete existing unpaid and not written-off payments
        if (!paymentsToDelete.isEmpty()) {
            try {
                Database.SaveResult[] deleteResults = Database.emptyRecycleBin(paymentsToDelete);
                // Handle errors appropriately
                for (Database.SaveResult result : deleteResults) {
                    if (!result.isSuccess()) {
                        throw new PaymentPlanException('Failed to delete existing payment: ' + result.getErrors()[0].getMessage());
                    }
                }
            } catch (DmlException e) {
                throw new PaymentPlanException('Failed to delete existing payments: ' + e.getMessage());
            }
        }

        // Calculate installment amount
        Decimal installmentAmount = outstandingAmount.divide(numberOfPayments, 2, System.RoundingMode.DOWN);
        Decimal lastInstallmentAmount = outstandingAmount - (installmentAmount * (numberOfPayments - 1));

        // Create new payments
        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Opportunity__c = opp.Id,
                npe01__Payment_Amount__c = (i == numberOfPayments - 1) ? lastInstallmentAmount : installmentAmount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            );
            newPayments.add(payment);
        }

        // Insert new payments
        if (!newPayments.isEmpty()) {
            try {
                Database.SaveResult[] insertResults = Database.insert(newPayments, false);
                // Handle errors appropriately
                for (Database.SaveResult result : insertResults) {
                    if (!result.isSuccess()) {
                        throw new PaymentPlanException('Failed to create payment: ' + result.getErrors()[0].getMessage());
                    }
                }
            } catch (DmlException e) {
                throw new PaymentPlanException('Failed to create payments: ' + e.getMessage());
            }
        }

        // Return payments in schedule order
        newPayments.sort((p1, p2) => p1.npe01__Scheduled_Date__c <= p2.npe01__Scheduled_Date__c ? -1 : 1);
        return newPayments;
    }
}
