public with sharing class RecordAccessService {
    private static final Integer BATCH_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        // Null or empty input returns an empty set (never null)
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        // Work with a copy so we don't modify the caller's collection
        Set<Id> remainingIds = new Set<Id>(recordIds);
        Set<Id> editableIds = new Set<Id>();

        Integer maxQueries = 20; // Governor limit for this method
        while (!remainingIds.isEmpty() && Limits.getQueries() < maxQueries) {
            // Take a batch of up to BATCH_SIZE ids for the UserRecordAccess query
            List<Id> batch = new List<Id>();
            for (Id recId : remainingIds) {
                batch.add(recId);
                if (batch.size() >= BATCH_SIZE) {
                    break;
                }
            }

            if (batch.isEmpty()) {
                break;
            }

            // Query UserRecordAccess for this batch with HasEditAccess filter
            List<UserRecordAccess> uraList = [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :batch
                  AND HasEditAccess = true
            ];

            for (UserRecordAccess ura : uraList) {
                editableIds.add(ura.RecordId);
            }

            // Remove processed ids from remainingIds to avoid re-querying
            remainingIds.removeAll(batch);
        }

        return editableIds;
    }
}
