```apex
public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    public static final String QUALIFYING_TYPE_1 = 'Customer - Direct';
    public static final String QUALIFYING_TYPE_2 = 'Customer - Channel';
    private static final Set<String> QUALIFYING_ACCOUNT_TYPES = new Set<String>{
        QUALIFYING_TYPE_1,
        QUALIFYING_TYPE_2
    };

    public void afterInsert(List<SObject> triggerNew) {
        List<Account> newAccounts = new List<Account>();
        for (SObject record : triggerNew) {
            Account acct = (Account) record;
            if (acct.Type != null && QUALIFYING_ACCOUNT_TYPES.contains(acct.Type)) {
                newAccounts.add(acct);
            }
        }
        if (newAccounts.isEmpty()) {
            return;
        }
        List<Task> tasksToInsert = new List<Task>();
        for (Account acct : newAccounts) {
            Task t = new Task(
                WhatId = acct.Id,
                OwnerId = acct.OwnerId,
                ActivityDate = Date.today().addDays(7),
                Status = 'Not Started',
                Priority = 'Normal',
                Subject = 'Onboard new customer'
            );
            tasksToInsert.add(t);
        }
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
```

