public with sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    public void beforeInsert(List<SObject> triggerNew) {
        List<SObject> contactsToCheck = new List<SObject>();
        for (SObject s : triggerNew) {
            Contact c = (Contact)s;
            if (c.AccountId != null && c.Email != null) {
                contactsToCheck.add(s);
            }
        }
        this.validateDuplicates(contactsToCheck, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<SObject> contactsToCheck = new List<SObject>();
        List<SObject> oldContacts = new List<SObject>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact newContact = (Contact)triggerNew[i];
            Contact oldContact = (Contact)triggerOld[i];
            if (newContact.Email != oldContact.Email || newContact.AccountId != oldContact.AccountId) {
                contactsToCheck.add(triggerNew[i]);
                oldContacts.add(triggerOld[i]);
            }
        }
        this.validateDuplicates(contactsToCheck, oldContacts);
    }

    private void validateDuplicates(List<SObject> contacts, List<SObject> oldContacts) {
        if (contacts.isEmpty()) {
            return;
        }

        Map<String, Id> emailToContactId = new Map<String, Id>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (SObject s : contacts) {
            Contact c = (Contact)s;
            emailToContactId.put(String.valueOf(c.AccountId) + '-' + c.Email.toLowerCase(), c.Id);
            accountIds.add(c.AccountId);
            emails.add(c.Email.toLowerCase());
        }

        // Query all contacts on the same accounts with the same emails
        Map<String, List<Contact>> accountEmailToContacts = new Map<String, List<Contact>>();
        List<Contact> existingContacts = [SELECT Id, AccountId, Email FROM Contact WHERE AccountId IN :accountIds AND Email IN :emails];
        for (Contact c : existingContacts) {
            String key = String.valueOf(c.AccountId) + '-' + c.Email.toLowerCase();
            if (!accountEmailToContacts.containsKey(key)) {
                accountEmailToContacts.put(key, new List<Contact>());
            }
            accountEmailToContacts.get(key).add(c);
        }

        Map<String, Contact> emailToFirstContact = new Map<String, Contact>();

        for (Integer i = 0; i < contacts.size(); i++) {
            Contact c = (Contact)contacts[i];
            String key = String.valueOf(c.AccountId) + '-' + c.Email.toLowerCase();

            // Check duplicates within the same save
            if (emailToFirstContact.containsKey(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                emailToFirstContact.put(key, c);
            }

            // Check against existing records
            if (accountEmailToContacts.containsKey(key)) {
                List<Contact> conflicts = accountEmailToContacts.get(key);
                for (Contact conflict : conflicts) {
                    // Skip self in update scenario
                    if (oldContacts != null && conflict.Id == ((Contact)oldContacts[i]).Id) {
                        continue;
                    }
                    c.addError('Another contact on this account already uses this email address.');
                    break;
                }
            }
        }
    }
}
