public without sharing class TA_Case_RollupOpenCount implements
    TriggerAction.AfterInsert,
    TriggerAction.AfterUpdate,
    TriggerAction.AfterDelete,
    TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalc(collectAccountIds(triggerNew, null));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        recalc(collectAccountIds(triggerNew, triggerOld));
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalc(collectAccountIds(null, triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalc(collectAccountIds(triggerNew, null));
    }

    private static Set<Id> collectAccountIds(List<SObject> newRecords, List<SObject> oldRecords) {
        Set<Id> accountIds = new Set<Id>();
        if (newRecords != null) {
            for (SObject record : newRecords) {
                Id accountId = (Id) record.get('AccountId');
                if (accountId != null) {
                    accountIds.add(accountId);
                }
            }
        }
        if (oldRecords != null) {
            for (SObject record : oldRecords) {
                Id accountId = (Id) record.get('AccountId');
                if (accountId != null) {
                    accountIds.add(accountId);
                }
            }
        }
        return accountIds;
    }

    private static void recalc(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }
        Map<Id, Integer> openCounts = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE IsClosed = false AND AccountId IN :accountIds
            GROUP BY AccountId
        ]) {
            openCounts.put((Id) ar.get('AccountId'), (Integer) ar.get('openCount'));
        }
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            Account acc = new Account(Id = accountId);
            Integer count = openCounts.get(accountId);
            acc.FB_Open_Case_Count__c = (count == null) ? 0 : count;
            accountsToUpdate.add(acc);
        }
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
